class Solution { public String minimumCover(String text, String required) { if(required.isEmpty())return "";int[] need=new int[128],have=new int[128];for(char c:required.toCharArray())need[c]++;int missing=required.length(),left=0,best=0,len=Integer.MAX_VALUE;for(int right=0;right<text.length();right++){char c=text.charAt(right);if(need[c]>0&&have[c]++<need[c])missing--;while(missing==0){if(right-left+1<len){best=left;len=right-left+1;}char x=text.charAt(left++);if(need[x]>0&&have[x]--<=need[x])missing++;}}return len==Integer.MAX_VALUE?"":text.substring(best,best+len); } }
